<?php
$field=function(string $name,string $label,string $type='text',string $attrs='')use($record){echo '<label>'.$label.'<input type="'.$type.'" name="'.$name.'" id="'.$name.'" value="'.e($record[$name]??'').'" '.$attrs.'></label>';};
$select=function(string $name,string $label,array $options)use($record){echo '<label>'.$label.'<select name="'.$name.'" id="'.$name.'" required><option value="">Selecciona una opción</option>';foreach($options as $o)echo '<option value="'.e($o['id']).'" '.((string)($record[$name]??'')===(string)$o['id']?'selected':'').'>'.e($o['nombre']).'</option>';echo '</select></label>';};
$ready=$catalogs['colonia']&&$catalogs['caja']&&$catalogs['tipo_padron'];
?>
<a class="back-link" href="<?= e($id?url('detalle',['id'=>$id]):url('padron')) ?>">← <?= $id?'Volver a la ficha':'Volver al padrón' ?></a><section class="page-heading"><div><span class="eyebrow">PIPAS / <?= $id?'EDICIÓN':'NUEVO REGISTRO' ?></span><h1><?= e($title) ?></h1><p><?= $id?'Actualiza la información del expediente.':'Completa los datos para incorporar un nuevo hogar al padrón.' ?></p></div><span class="count-pill"><?= $id?'Folio '.e($record['folio']):'El folio se asignará al guardar' ?></span></section>
<?php if($error):?><div class="alert danger" role="alert"><div><?= e($error) ?><?php if($duplicateId):?> <a href="<?= e(url('detalle',['id'=>$duplicateId])) ?>">Ver ficha existente →</a><?php endif;?></div></div><?php endif;?>
<?php if(!$ready):?><div class="alert info"><span>Faltan catálogos de colonia, garza o tipo de padrón. <?php if(can('manage')):?><a href="<?= e(url('catalogos')) ?>">Configúralos para continuar.</a><?php else:?>Solicita su carga a ROOT.<?php endif;?></span></div><?php endif;?>
<div class="form-layout"><form method="post" class="beneficiary-form" id="beneficiary-form" data-geocode-url="<?= e(url('geocode')) ?>"><?= csrf() ?><?php if($id):?><input type="hidden" name="version" value="<?= e($record['version']) ?>"><?php endif;?>
<section class="card form-section" id="datos-personales"><header class="section-title"><span class="section-number">01</span><div><h2>Datos del beneficiario</h2><p>Identidad y medios de contacto.</p></div></header><div class="form-grid three"><?php $field('nombre','Nombre(s) *','text','required maxlength="45" autocomplete="given-name"');$field('paterno','Apellido paterno *','text','required maxlength="45"');$field('materno','Apellido materno','text','maxlength="45"');?><div class="field-with-help"><?php $field('curp','CURP *','text','required minlength="18" maxlength="18" autocapitalize="characters" aria-describedby="curp-help"');?><small id="curp-help" aria-live="polite">18 caracteres, con dígito verificador.</small></div><?php $field('telefono','Teléfono','tel','maxlength="10" pattern="[0-9]{10}" autocomplete="tel"');$field('email','Correo electrónico','email','maxlength="100" autocomplete="email"');$field('cotitular','Cotitular','text','maxlength="300"');$field('num_exp','Número de expediente','text','maxlength="11"');$select('tipo_padron_id_tipo_padron','Tipo de padrón *',$catalogs['tipo_padron']);?></div></section>
<section class="card form-section" id="domicilio"><header class="section-title"><span class="section-number">02</span><div><h2>Domicilio y ubicación</h2><p>Dirección del inmueble que recibirá el servicio.</p></div></header><div class="form-grid three"><?php $select('colonia_id_colonia','Colonia *',$catalogs['colonia']);$field('calle','Calle *','text','required maxlength="100"');$field('cp','Código postal','text','maxlength="5" pattern="[0-9]{5}" inputmode="numeric"');$field('num_ext_mza','Número exterior / manzana *','text','required maxlength="50"');$field('num_int_lote','Número interior / lote','text','maxlength="50"');$field('tiempo_residencia','Tiempo de residencia','text','maxlength="20" placeholder="Ej. 5 años"');$field('num_familias','Número de familias *','number','required min="1" max="100000"');$field('num_habitantes','Número de habitantes *','number','required min="1" max="100000"');?></div><div class="form-grid two spaced"><label>Referencias del domicilio<textarea name="observacion" maxlength="300" rows="3"><?= e($record['observacion']??'') ?></textarea></label><label>Descripción del croquis<textarea name="croquis" maxlength="300" rows="3"><?= e($record['croquis']??'') ?></textarea></label></div><div class="location-panel"><div class="location-heading"><span><?= icon('pin') ?><strong>Ubicación del inmueble</strong></span><?php if($config['google_maps_key']):?><button type="button" class="button secondary" id="geocode">Buscar dirección <?= icon('pin') ?></button><?php endif;?></div><p class="map-intro">Acerca el mapa y haz clic sobre el inmueble. Puedes arrastrar el marcador para ajustar el punto.</p><div id="address-map" class="address-map" role="region" aria-label="Mapa para seleccionar la ubicación del inmueble"></div><div class="map-toolbar"><span class="map-selection" id="map-selection" role="status">Sin punto seleccionado</span><div><button type="button" class="button secondary tiny" id="map-center">Marcar el centro</button><button type="button" class="button secondary tiny" id="map-clear">Quitar punto</button></div></div><p id="map-load-status" class="field-note" role="status"></p><div class="form-grid two"><?php $field('latitud','Latitud','number','step="0.0000001" min="-90" max="90"');$field('longitud','Longitud','number','step="0.0000001" min="-180" max="180"');?></div><p class="small muted" id="geocode-status" aria-live="polite"><?= $config['google_maps_key']?'Busca la dirección y verifica el punto sugerido antes de guardar.':'Selecciona el inmueble en el mapa o captura sus coordenadas. La búsqueda automática por dirección aún no está habilitada.' ?></p></div></section>
<section class="card form-section" id="dotacion"><header class="section-title"><span class="section-number">03</span><div><h2><?= $id?'Datos del suministro':'Dotación inicial' ?></h2><p>Cuota de agua y asignación operativa.</p></div></header><div class="form-grid two"><?php if(!$id):?><label>Viajes por mes *<select name="dotacion" required><option value="">Selecciona la cuota</option><?php for($i=1;$i<=5;$i++):?><option value="<?= $i ?>" <?= (int)($record['dotacion']??0)===$i?'selected':'' ?>><?= $i ?> <?= $i===1?'viaje':'viajes' ?> por mes</option><?php endfor;?></select></label><?php else:?><div class="readonly-field"><span>Dotación vigente</span><strong><?= e($record['dotacion']) ?> viajes por mes</strong><small>Los cambios de cuota se registran desde Dotación.</small></div><?php endif;?><?php $field('tamano_cisterna','Capacidad de cisterna (litros) *','number','required min="1" max="10000000"');$field('tarifa','Tarifa por viaje (MXN) *','number','required min="0" max="9999999.99" step="0.01"');$select('id_caja','Garza / caja asignada *',$catalogs['caja']);?></div></section>
<div class="form-footer"><span class="small muted">* Campos obligatorios</span><div><a class="button secondary" href="<?= e($id?url('detalle',['id'=>$id]):url('padron')) ?>">Cancelar</a><button class="button primary" <?= !$ready?'disabled':'' ?> type="submit"><?= icon('check') ?> <?= $id?'Guardar cambios':'Registrar beneficiario' ?></button></div></div></form><aside class="form-guide"><span class="eyebrow">EN ESTE REGISTRO</span><a href="#datos-personales"><span>01</span>Datos del beneficiario</a><a href="#domicilio"><span>02</span>Domicilio y ubicación</a><a href="#dotacion"><span>03</span><?= $id?'Datos del suministro':'Dotación inicial' ?></a><div class="guide-note"><?= icon('lock') ?><h3>Un expediente por hogar</h3><p>La CURP y el domicilio se verifican al guardar para evitar registros duplicados.</p><p>La cuota inicial permite de 1 a 5 viajes mensuales.</p></div></aside></div>
